import{_ as e,o as s,c as a,aO as d}from"./chunks/framework.vjUPZZJn.js";const g=JSON.parse('{"title":"Git 常用命令速查","description":"","frontmatter":{"date":"2026-10-08T20:00:00.000Z","title":"Git 常用命令速查","source":[[["1-知识/工具/Git/git 命令整理"]],[["1-知识/工具/Git/修改已 push 的 commit 信息"]],[["1-知识/工具/Git/git 同步代码提示：会破坏现有标签"]],[["1-知识/工具/Git/git pull、git fetch、git merge 与 git rebase"]]],"tags":["工具","教程手册","问题排查","git"],"categories":["工具"],"permalink":"/pages/59d122"},"headers":[],"relativePath":"工具/Git 常用命令速查.md","filePath":"工具/Git 常用命令速查.md","lastUpdated":1792376995000}'),i={name:"工具/Git 常用命令速查.md"};function n(r,t,l,c,o,p){return s(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="git-常用命令速查" tabindex="-1">Git 常用命令速查 <a class="header-anchor" href="#git-常用命令速查" aria-label="Permalink to &quot;Git 常用命令速查&quot;">​</a></h1> <p>按功能分类整理 Git 常用命令，覆盖日常开发的配置、提交、分支、远程协作与标签操作；随后讲清 <code>git pull</code>、<code>git fetch</code>、<code>git merge</code> 与 <code>git rebase</code> 四个命令的关系与分工，末尾补充两个常见问题的处理：本地 tag 与远程不一致导致同步被拒、修改已推送的提交信息。适合放在手边随查随用。</p> <h2 id="命令速查表" tabindex="-1">命令速查表 <a class="header-anchor" href="#命令速查表" aria-label="Permalink to &quot;命令速查表&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>类别</th> <th>命令</th> <th>说明</th></tr></thead> <tbody><tr><td>配置</td> <td><code>git config --global user.name &quot;Your Name&quot;</code></td> <td>设置全局用户名</td></tr> <tr><td></td> <td><code>git config --global user.email &quot;email@example.com&quot;</code></td> <td>设置全局邮箱</td></tr> <tr><td></td> <td><code>git config --list</code></td> <td>查看当前配置</td></tr> <tr><td>初始化</td> <td><code>git init</code></td> <td>初始化一个新的 Git 仓库</td></tr> <tr><td></td> <td><code>git clone &lt;url&gt;</code></td> <td>克隆远程仓库到本地</td></tr> <tr><td>查看状态</td> <td><code>git status</code></td> <td>查看工作区状态（哪些文件被修改、暂存等）</td></tr> <tr><td>添加与提交</td> <td><code>git add &lt;file&gt;</code></td> <td>将指定文件添加到暂存区</td></tr> <tr><td></td> <td><code>git add .</code></td> <td>添加当前目录所有更改到暂存区</td></tr> <tr><td></td> <td><code>git commit -m &quot;commit message&quot;</code></td> <td>提交暂存区内容到本地仓库，并附带提交信息</td></tr> <tr><td>查看历史</td> <td><code>git log</code></td> <td>查看提交历史（详细）</td></tr> <tr><td></td> <td><code>git log --oneline</code></td> <td>以单行形式显示提交历史</td></tr> <tr><td></td> <td><code>git log --graph --all --oneline</code></td> <td>图形化显示所有分支的提交历史</td></tr> <tr><td>差异比较</td> <td><code>git diff</code></td> <td>查看工作区与暂存区之间的差异</td></tr> <tr><td></td> <td><code>git diff --staged</code> 或 <code>git diff --cached</code></td> <td>查看暂存区与最新提交之间的差异（两者等价）</td></tr> <tr><td>撤销操作</td> <td><code>git checkout -- &lt;file&gt;</code></td> <td>丢弃工作区对文件的修改（恢复到最近一次暂存/提交状态）</td></tr> <tr><td></td> <td><code>git reset HEAD &lt;file&gt;</code></td> <td>从暂存区移除文件（保留工作区修改）</td></tr> <tr><td></td> <td><code>git reset --hard HEAD~1</code></td> <td>回退到上一个提交（会丢失最近一次提交的所有更改），慎用</td></tr> <tr><td>分支管理</td> <td><code>git branch</code></td> <td>列出本地所有分支</td></tr> <tr><td></td> <td><code>git branch &lt;branch-name&gt;</code></td> <td>创建新分支</td></tr> <tr><td></td> <td><code>git checkout &lt;branch-name&gt;</code></td> <td>切换到指定分支</td></tr> <tr><td></td> <td><code>git switch &lt;branch-name&gt;</code></td> <td>（Git 2.23+）切换分支（推荐替代 checkout）</td></tr> <tr><td></td> <td><code>git checkout -b &lt;branch-name&gt;</code></td> <td>创建并切换新分支</td></tr> <tr><td></td> <td><code>git branch -d &lt;branch-name&gt;</code></td> <td>删除已合并的分支</td></tr> <tr><td></td> <td><code>git branch -D &lt;branch-name&gt;</code></td> <td>强制删除分支（即使未合并）</td></tr> <tr><td></td> <td><code>git merge &lt;branch-name&gt;</code></td> <td>合并指定分支到当前分支</td></tr> <tr><td>远程操作</td> <td><code>git remote -v</code></td> <td>查看远程仓库地址</td></tr> <tr><td></td> <td><code>git remote add origin &lt;url&gt;</code></td> <td>添加远程仓库（通常命名为 origin）</td></tr> <tr><td></td> <td><code>git push -u origin &lt;branch&gt;</code></td> <td>首次推送本地分支到远程，并设置上游跟踪</td></tr> <tr><td></td> <td><code>git push</code></td> <td>推送当前分支到关联的远程分支</td></tr> <tr><td></td> <td><code>git pull</code></td> <td>拉取远程更新并合并（默认相当于 fetch + merge）</td></tr> <tr><td></td> <td><code>git fetch</code></td> <td>获取远程更新但不合并</td></tr> <tr><td>标签管理</td> <td><code>git tag</code></td> <td>列出所有标签</td></tr> <tr><td></td> <td><code>git tag &lt;tagname&gt;</code></td> <td>创建轻量标签</td></tr> <tr><td></td> <td><code>git tag -a &lt;tagname&gt; -m &quot;message&quot;</code></td> <td>创建带注释的标签</td></tr> <tr><td></td> <td><code>git push origin &lt;tagname&gt;</code></td> <td>推送指定标签到远程</td></tr> <tr><td></td> <td><code>git push origin --tags</code></td> <td>推送所有标签到远程</td></tr> <tr><td>其他实用命令</td> <td><code>git stash</code></td> <td>临时保存当前工作区和暂存区的修改</td></tr> <tr><td></td> <td><code>git stash pop</code></td> <td>恢复最近一次 stash 的内容</td></tr> <tr><td></td> <td><code>git reflog</code></td> <td>查看 HEAD 变更记录（可用于找回「丢失」的提交）</td></tr> <tr><td></td> <td><code>git show &lt;commit-id&gt;</code></td> <td>显示某次提交的详细信息</td></tr></tbody></table> <h2 id="pull、fetch、merge-与-rebase-的关系" tabindex="-1">pull、fetch、merge 与 rebase 的关系 <a class="header-anchor" href="#pull、fetch、merge-与-rebase-的关系" aria-label="Permalink to &quot;pull、fetch、merge 与 rebase 的关系&quot;">​</a></h2> <p><code>git fetch</code> 与 <code>git pull</code> 都用于更新本地代码，区别在于是否合并：</p> <ul><li><code>git fetch</code> 只获取远端仓库的分支数据，更新本地的远程跟踪分支（如 <code>origin/master</code>），<strong>不进行合并</strong>，工作区不受影响</li> <li><code>git pull</code> 在 fetch 的基础上更进一步。<a href="https://git-scm.com/docs/git-pull" target="_blank" rel="noreferrer">官方文档</a>的描述：把远端仓库的变更合入当前分支——当前分支落后于远端时，默认 fast-forward（快进）到远端；两者发生分歧时，需要通过 <code>--rebase</code> 或 <code>--no-rebase</code>（或 <code>pull.rebase</code> 配置）指定调和方式</li></ul> <p>更准确地说，<code>git pull</code> 先执行 <code>git fetch</code>，然后根据配置或命令行参数调用 <code>git merge</code> 或 <code>git rebase</code> 完成分支调和，默认是 merge。</p> <p>merge 与 rebase 处理分歧的结果不同。假设当前分支与远端出现如下分歧：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     A---B---C master on origin</span></span>
<span class="line"><span>    /</span></span>
<span class="line"><span>D---E---F---G feature</span></span>
<span class="line"><span>    ^     origin/master in your repository</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>git pull</code>（merge 方式）会把远端新提交（A、B、C）合并到当前分支，创建一个新的合并提交 H：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      A---B---C origin/master</span></span>
<span class="line"><span>     /         \\</span></span>
<span class="line"><span>D---E---F---G---H  feature</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>rebase 则把当前分支上不在上游（<code>&lt;upstream&gt;</code>）中的提交（F、G）暂存到临时区域，将分支重置到上游最新提交，再把这些提交逐个重放到顶部。上游提交 C 不会被改写，被改写的是自己的 F、G（变成 F&#39;、G&#39;）：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      A---B---C---F&#39;--G&#39; feature</span></span>
<span class="line"><span>     /</span></span>
<span class="line"><span>D---E</span></span>
<span class="line"><span>    ^  origin/master in your repository</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>merge 保留真实的分叉历史，rebase 产出线性的历史记录。整理已有提交历史的更多操作（交互式 rebase、cherry-pick）见 <a href="./Git Rebase 与 Cherry-pick 实用指南.html">Git Rebase 与 Cherry-pick 实用指南</a>。</p> <h2 id="修改已推送的-commit-信息" tabindex="-1">修改已推送的 commit 信息 <a class="header-anchor" href="#修改已推送的-commit-信息" aria-label="Permalink to &quot;修改已推送的 commit 信息&quot;">​</a></h2> <p>场景：最近一次 commit 已经推送到远端，发现提交信息写错了，想改过来。前提是本地处于该分支最新状态。</p> <ol><li><code>git commit --amend</code> 进入编辑器（默认 vim）：按 <code>i</code> 进入编辑模式修改提交信息，编辑完按 <code>Esc</code>，输入 <code>:wq</code> 保存退出</li> <li><code>git push -f</code> 强制推送，覆盖远端</li></ol> <p>编辑器不一定是 vim，能保存即可，例如 nano：<code>Ctrl+O</code> 保存，<code>Ctrl+X</code> 退出。</p> <p>force push 会改写远端历史：该 commit 已被他人拉取时，会给他们制造冲突，共享分支上慎用。更稳妥的写法是 <code>git push --force-with-lease</code>——远端在本地不知情时被更新过，推送会被拒绝，降低覆盖他人提交的风险。</p> <h2 id="本地-tag-与远程不一致导致同步被拒" tabindex="-1">本地 tag 与远程不一致导致同步被拒 <a class="header-anchor" href="#本地-tag-与远程不一致导致同步被拒" aria-label="Permalink to &quot;本地 tag 与远程不一致导致同步被拒&quot;">​</a></h2> <p>场景：<code>git pull</code> / <code>git fetch</code> 时报错，同步中断：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ! [rejected] v3.38.0 -&gt; v3.38.0  (would clobber existing tag)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>本地存在与远程同名的 tag，但两者指向不同的提交。常见原因是本地重新打过这个 tag（如 <code>git tag -f</code>），或者远程 tag 被人删掉重建过。Git 出于安全考虑拒绝覆盖本地 tag。</p> <p>处理思路是删掉不一致的本地 tag，再从远程重新拉取：</p> <ol><li>查看远程 tag：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls-remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">remot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>查看本地 tag：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="3"><li>删除与远程不一致的本地 tag：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v3.38.0</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="4"><li>重新拉取远程 tag 并同步代码：</li></ol> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>关于 <code>--prune-tags</code>：<code>git fetch origin --prune-tags</code> 会按 <code>refs/tags/*:refs/tags/*</code> 强制拉取远程全部 tag，但单独使用时并不会清理本地多余的 tag——<a href="https://git-scm.com/docs/git-fetch" target="_blank" rel="noreferrer">官方文档</a>写明，清理仅在 <code>--prune</code> 同时启用时生效。要一步清掉本地已不在远程的 tag，用：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prune</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prune-tags</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也可以写进配置长期生效：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch.prune</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch.pruneTags</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>查任意命令的权威说明用 <code>git help &lt;command&gt;</code></li> <li><code>--hard</code> 与 force push 都是破坏性操作，执行前确认自己清楚后果</li> <li>Git 2.23 起分支操作推荐用 <code>git switch</code>、撤销暂存推荐用 <code>git restore --staged</code>，职责比 <code>git checkout</code> 清晰</li></ul>`,67)])])}const u=e(i,[["render",n]]);export{g as __pageData,u as default};
